package org.animallink.gateway;
import java.time.Duration;import java.util.Map;import org.springframework.beans.factory.annotation.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.reactive.function.client.WebClient;import reactor.core.publisher.Mono;
@RestController public class WechatAdoptionController {
 private final WechatSessionClient sessions;private final AdoptionMiniappAssertionSigner signer;private final WebClient client;
 public WechatAdoptionController(WechatSessionClient sessions,AdoptionMiniappAssertionSigner signer,@Qualifier("identitySessionWebClientBuilder") WebClient.Builder builder,@Value("${animallink.authentication.adoption-miniapp.base-url:http://adoption-service}") String url){this.sessions=sessions;this.signer=signer;this.client=builder.clone().baseUrl(url).build();}
 @PostMapping("/auth/wechat/adoption/listings/{id}/applications") public Mono<ResponseEntity<?>> submit(@RequestHeader(value="X-Miniapp-Session",required=false) String token,@PathVariable("id") String id,@RequestBody Map<String,Object> body){return call(token,"POST","/auth/wechat/adoption/listings/"+id+"/applications",body,"");}
 @GetMapping("/auth/wechat/adoption/applications") public Mono<ResponseEntity<?>> mine(@RequestHeader(value="X-Miniapp-Session",required=false) String token,@RequestParam(name="page",defaultValue="0") int page,@RequestParam(name="size",defaultValue="20") int size){if(page<0||size<1||size>100)return Mono.just(ResponseEntity.badRequest().build());return call(token,"GET","/auth/wechat/adoption/applications",null,"?page="+page+"&size="+size);}
 @GetMapping("/auth/wechat/adoption/applications/{id}") public Mono<ResponseEntity<?>> detail(@RequestHeader(value="X-Miniapp-Session",required=false) String token,@PathVariable("id") String id){return call(token,"GET","/auth/wechat/adoption/applications/"+id,null,"");}
 @PostMapping("/auth/wechat/adoption/applications/{id}/withdraw") public Mono<ResponseEntity<?>> withdraw(@RequestHeader(value="X-Miniapp-Session",required=false) String token,@PathVariable("id") String id){return call(token,"POST","/auth/wechat/adoption/applications/"+id+"/withdraw",null,"");}
 private Mono<ResponseEntity<?>> call(String token,String method,String path,Object body,String query){if(token==null||token.isBlank())return Mono.just(WechatRescueClaimController.failure(new WechatSessionClient.Invalid()));if(!AdoptionMiniappGatewayPolicy.allowed(method,path))return Mono.just(ResponseEntity.badRequest().build());return sessions.current(token).flatMap(user->Mono.fromCallable(()->signer.sign(user.userId(),user.systemRole(),method,path)).flatMap(assertion->{var spec=client.method(HttpMethod.valueOf(method)).uri(AdoptionMiniappGatewayPolicy.downstreamPath(path)+query).header(HttpHeaders.AUTHORIZATION,"Bearer "+assertion);var request=body==null?spec:spec.contentType(MediaType.APPLICATION_JSON).bodyValue(body);return request.exchangeToMono(response->{if(response.statusCode().is2xxSuccessful())return response.bodyToMono(Object.class).map(value->(ResponseEntity<?>)ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(value));int status=response.statusCode().value();return response.releaseBody().thenReturn(ResponseEntity.status(status==401?503:status).build());});})).timeout(Duration.ofSeconds(15)).onErrorResume(e->Mono.just(WechatRescueClaimController.failure(e)));}
}
